import {potionIcon} from './consumable-pixel-art.js';
import {POTION_BUFF_KEYS} from './potion-catalog.js';
import {POTIONS,RARITY,potionEntries,parsePotionKey,potionEffect,resolvePotionKey,resolveHealingPotionKey,potionCooldownUntil,maxPotionUseQuantity} from './engine.js';
import {icon} from './icons.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const remaining=(end,now)=>Math.max(0,Math.ceil((Number(end)-now)/1000)||0);
const qualityClass=p=>Number.isInteger(p?.quality)&&p.quality>=0&&p.quality<=3?'potionQ'+p.quality:'';
const qualityTitle=p=>p?.qualityName?' · '+p.qualityName:'';
const clock=seconds=>`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
const elementNames={earth:'地',water:'水',fire:'火',wind:'风',light:'光',dark:'暗'};
export function potionDescription(type,quality){const f=potionEffect(type,quality);if(!f)return '';if(type==='healing')return `恢复${Math.round(f.healFraction*100)}%最大生命；自动：生命不高于40%时饮用。`;const label=f.kind==='attack'?'攻击 +'+f.attack:f.kind==='luckPoints'?'幸运 +'+f.luck:f.kind==='elementAttack'?elementNames[f.element]+'元素技能增幅 +'+f.elementAttack:elementNames[f.element]+'抗性 +'+f.elementResistance;return label+'，持续5分钟；同品质延长时长，高品质替换，低品质不消耗。';}
/** Pure renderer. Times are epoch milliseconds; potions/buffs contain display-ready descriptions. */
export function renderPotionPanel(s,{potions=[],selected=null,auto=false,now=Date.now(),cooldownUntil=undefined,buffs=[],restUntil=0}={}){
 const carried=potions.find(p=>p.id===selected),rest=remaining(restUntil,now),cooldown=remaining(cooldownUntil??potionCooldownUntil(s,selected),now),active=buffs.filter(b=>remaining(b.endAt,now)>0),count=Math.max(0,Number(carried?.count)||0),disabled=rest>0||cooldown>0||!carried||count<1;
 const action=rest?`休整 ${clock(rest)}`:cooldown?`冷却 ${clock(cooldown)}`:!carried?'选择药剂':count<1?'药剂不足':'饮用';
 return `<section class="potionPanel" aria-label="药剂携带与饮用"><div class="potionTop"><div class="potionCarry ${carried?'is-filled':''} ${qualityClass(carried)}" title="独立药剂栏：同时携带一种药剂${esc(qualityTitle(carried))}"><span class="potionCarryIcon">${carried?potionIcon(carried.type??parsePotionKey(carried.id)?.type,{size:48}):'<span class="potionEmpty">+</span>'}</span><div><span class="potionEyebrow">药剂栏</span><strong>${carried?esc(carried.name):'未携带'}</strong><small>${carried?'库存 ×'+count:'选择一种药剂'}</small></div></div><div class="potionActions"><button type="button" class="potionAuto ${auto?'is-on':''}" data-potionauto="1" aria-pressed="${auto?'true':'false'}" title="按药剂触发条件自动饮用"><span class="potionSwitch" aria-hidden="true"></span>自动</button><button type="button" class="primary potionDrink" data-potiondrink="1" ${disabled?'disabled':''} ${rest?'title="休整结束前不能饮用药剂"':''}>${action}</button></div></div><div class="potionStock" aria-label="选择携带药剂">${potions.map(p=>`<button type="button" class="potionStockItem ${selected===p.id?'is-selected':''} ${qualityClass(p)}" data-potionselect="${esc(p.id)}" aria-pressed="${selected===p.id?'true':'false'}" title="${esc((p.description||p.name)+qualityTitle(p))}" aria-label="${esc(p.name+qualityTitle(p))}">${potionIcon(p.type??parsePotionKey(p.id)?.type,{size:48})}<span><strong>${esc(p.name)}</strong><small>×${Math.max(0,Number(p.count)||0)}</small></span></button>`).join('')}</div>${carried?.description?`<p class="potionDescription">${esc(carried.description)}</p>`:''}${active.length?`<div class="potionBuffs" aria-label="当前药剂效果">${active.map(b=>`<div class="potionBuff" title="${esc(b.description||b.name)}">${potionIcon(b.type??b.id,{size:32})}<span>${esc(b.name)}</span><b>${clock(remaining(b.endAt,now))}</b></div>`).join('')}</div>`:''}<div class="potionFootnote">仅生命药剂冷却10秒<span>${rest?'休整中仍可更换携带药剂':'同类增益延长时间，不叠加强度'}</span></div></section>`;
}

export function renderBattlePotionButton(s,now=Date.now()){
 const key=resolveHealingPotionKey(s,now),chosen=parsePotionKey(key),count=potionEntries(s).filter(p=>p.type==='healing').reduce((n,p)=>n+p.count,0),cd=remaining(s.potionReadyAt,now);
 return `<button class="battlePotionButton ${chosen?'potionQ'+chosen.quality:''}" data-potion-settings="1" title="生命药剂 · 自动使用设置" aria-label="生命药剂设置，库存${count}，冷却${cd}秒">${potionIcon('healing',{size:32})}<span class="battlePotionType">${count?'生命':'无生命药剂'}</span><b>×${count}</b>${cd?`<span class="battlePotionShade" style="--cooldown:${Math.min(1,cd/10)}"><strong>${cd}s</strong></span>`:''}</button>`;
}
export function renderPotionSettings(s){
 const now=Math.max(Date.now(),s.lastHealthClock||0),rows=potionEntries(s).filter(p=>p.type==='healing'),cd=remaining(s.potionReadyAt,now),rest=remaining(s.restUntil,now),empty=!rows.length;
 return `<section class="battleHealingSettings"><h2>生命药剂</h2>${empty?'<p class="emptyMessage">无生命药剂</p>':`<div class="ownedHealingStock">${rows.map(p=>`<div class="potionQ${p.quality}">${potionIcon('healing',{size:48})}<span>${RARITY[p.quality]}</span><b>×${p.count}</b></div>`).join('')}</div>`}<label class="potionAutoSetting"><input type="checkbox" data-healing-auto="1" ${s.potionSlot?.auto?'checked':''}>生命不高于40%时自动使用</label><div class="potionPriorityChoices"><button data-potion-priority="low" aria-pressed="${s.potionSlot?.priority!=='high'}">低品质优先</button><button data-potion-priority="high" aria-pressed="${s.potionSlot?.priority==='high'}">高品质优先</button></div>${empty?'':`<button class="primary" data-battle-potion-drink="1" ${cd||rest?'disabled':''}>${rest?'营地休息中':cd?'冷却 '+cd+' 秒':'使用生命药剂'}</button>`}<p class="potionDescription">生命药剂独立冷却 10 秒，不受功能药剂影响。功能药剂在背包中使用。</p></section>`;
}
export function clampPotionUseQuantity(max,value=1){const n=Number(value);return Math.max(1,Math.min(Math.max(1,max),Number.isSafeInteger(n)?n:1));}
export function renderPotionInventory(s,now=Date.now(),{quantities={}}={}){
 const clockNow=Math.max(now,s.lastHealthClock||0),rows=potionEntries(s),rest=remaining(s.restUntil,clockNow),active=POTION_BUFF_KEYS.filter(type=>remaining(s.potionBuffs?.[type]?.endAt,clockNow)>0);
 return `<section class="inventoryPotionStock" aria-label="已有药剂"><p class="potionDescription">仅生命药剂冷却10秒；其他药剂无使用冷却，可批量使用。每瓶增加5分钟，同品质延长时间，高品质替换，效果强度不叠加。</p>${rows.length?rows.map(p=>{const healing=p.type==='healing',cd=remaining(potionCooldownUntil(s,p.key),clockNow),max=healing?1:maxPotionUseQuantity(s,p.key,clockNow),quantity=clampPotionUseQuantity(max,quantities[p.key]),disabled=!!(cd||rest||!max),label=rest?'休息中':cd?'冷却 '+cd+'s':!max?'当前不可用':healing?'使用':'使用 ×'+quantity;return `<article class="inventoryPotionCard potionQ${p.quality}">${potionIcon(p.type,{size:48})}<div><strong>${esc(POTIONS[p.type].name)}</strong><small>${RARITY[p.quality]} · ×${p.count}</small><p>${esc(potionDescription(p.type,p.quality))}</p></div><div class="potionUseControls">${healing?'':`<label>数量<input type="number" inputmode="numeric" min="1" max="${Math.max(1,max)}" step="1" value="${quantity}" data-potion-use-quantity="${esc(p.key)}" aria-label="${esc(POTIONS[p.type].name)}使用数量" ${disabled?'disabled':''}></label><button type="button" data-potion-use-max="${esc(p.key)}" ${disabled?'disabled':''}>全部</button>`}<button type="button" data-potion-use="${esc(p.key)}" ${disabled?'disabled':''}>${label}</button></div></article>`;}).join(''):'<p class="emptyMessage">暂无药剂</p>'}${active.length?`<div class="potionBuffs">${active.map(type=>`<div class="potionBuff">${potionIcon(type,{size:32})}<span>${esc(POTIONS[type].name)}</span><b>${clock(remaining(s.potionBuffs[type].endAt,clockNow))}</b></div>`).join('')}</div>`:''}</section>`;
}
